from machine import Pin, PWM, ADC
import time

lamp = PWM(Pin(15), freq=1000, duty_u16=0)
_level_lamp = 0
button = Pin(4, Pin.IN, Pin.PULL_UP)
level = 0
_lastRaw0 = False
_stable0 = False
_changedAt0 = 0

# ---- runs once ----
level = 0

# ---- runs forever ----
while True:
    # when button pressed (line 9)
    _raw0 = (button.value() == 0)
    if _raw0 != _lastRaw0:
        _lastRaw0 = _raw0
        _changedAt0 = time.ticks_ms()
    if time.ticks_diff(time.ticks_ms(), _changedAt0) > 30 and _raw0 != _stable0:
        _stable0 = _raw0
        if _stable0:
            level = level + 25
            if level > 100:
                level = 0
            print("Brightness: " + str(level) + "%")
            _from1 = _level_lamp
            _to1 = max(0, min(100, level))
            _ms1 = 300
            for _s1 in range(1, 51):
                _level_lamp = _from1 + (_to1 - _from1) * _s1 // 50
                lamp.duty_u16(_level_lamp * 65535 // 100)
                time.sleep_ms(_ms1 // 50)
